def verify_owned_files(
    component_id: str,
    source_root: Path,
    files: list[tuple[Path, str]],
    runtime_dependency_paths: set[str],
    catalog_path: Path = OWNERSHIP_CATALOG,
) -> None:
    owned = owned_tracked_paths(component_id, source_root, catalog_path)
    actual = {relative_path for _, relative_path in files}
    expected = owned | runtime_dependency_paths
    if actual != expected:
        missing = sorted(expected - actual)
